import java.util.Scanner;

public class Main {
    public static double getAbs(double val) {
        return val < 0 ? -val : val;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
        int n = sc.nextInt();

        int ans_x = 0;
        int ans_y = 0;
        double min_diff = 1e100;

        for (int i = 1; i <= n; i++) {
            int x = i;
            int y1 = (int)((double)a / b * i);
            int y2 = y1 + 1;

            double diff1 = getAbs((double)a / b - (double)y1 / x);
            double diff2 = getAbs((double)a / b - (double)y2 / x);

            if (min_diff > diff1) {
                min_diff = diff1;
                ans_x = y1;
                ans_y = x;
            }
            if (min_diff > diff2) {
                min_diff = diff2;
                ans_x = y2;
                ans_y = x;
            }
        }
        System.out.println(ans_x + "/" + ans_y);
        sc.close();
    }
}
